#!/usr/bin/env python3

import argparse
import errno
import os
import re
import sys

HEADER = [
    "# ansible-pve: per-container SMBIOS system UUIDs",
    "# Generated by roles/pve-common-ct-uuid; read by pve-ct-dmi-sync.sh at boot.",
    "# Do not edit by hand: the source of truth is group_vars/pve.yml.",
]
UUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")

class RegistryError(Exception):
    pass

CHMOD_TOLERATED = {errno.EPERM, errno.EACCES, errno.EOPNOTSUPP}

def chmod_best_effort(path, mode):
    try:
        os.chmod(path, mode)
    except OSError as exc:
        if exc.errno not in CHMOD_TOLERATED:
            raise

def parse_file(text, source="<registry>"):

    table = {}
    for number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = stripped.split()
        if len(fields) != 2 or not fields[0].isdigit():
            raise RegistryError("%s:%d: expected '<vmid> <uuid>', got %r" % (source, number, line))
        vmid = int(fields[0])
        value = fields[1].lower()
        if not UUID_RE.match(value):
            raise RegistryError("%s:%d: %r is not a canonical UUID" % (source, number, fields[1]))
        if vmid in table and table[vmid] != value:
            raise RegistryError("%s:%d: vmid %d appears twice with different UUIDs"
                                % (source, number, vmid))
        table[vmid] = value
    return table

def render(table):
    lines = list(HEADER)
    lines.extend("%d %s" % (vmid, table[vmid]) for vmid in sorted(table))
    return "\n".join(lines) + "\n"

def read_table(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return parse_file(handle.read(), path)
    except FileNotFoundError:
        return {}
    except OSError as exc:
        raise RegistryError("cannot read %s: %s" % (path, exc))

def write_table(path, table):
    payload = render(table)
    try:
        with open(path, "r", encoding="utf-8") as handle:
            if handle.read() == payload:
                chmod_best_effort(path, 0o644)
                return False
    except FileNotFoundError:
        pass
    directory = os.path.dirname(os.path.abspath(path))
    if not os.path.isdir(directory):
        os.makedirs(directory, mode=0o700)
        chmod_best_effort(directory, 0o700)
    tmp = os.path.join(directory, ".%s.ansible-pve.tmp" % os.path.basename(path))
    with open(tmp, "w", encoding="utf-8") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    chmod_best_effort(tmp, 0o644)
    os.replace(tmp, path)
    return True

def parse_set(value):
    vmid, _, system_uuid = value.partition("=")
    if not vmid.strip().isdigit():
        raise RegistryError("--set %r: expected <vmid>=<uuid>" % value)
    system_uuid = system_uuid.strip().lower()
    if not UUID_RE.match(system_uuid):
        raise RegistryError("--set %r: %r is not a canonical UUID" % (value, system_uuid))
    return int(vmid), system_uuid

def main(argv=None):
    parser = argparse.ArgumentParser(description="Maintain the vmid -> SMBIOS system UUID table of one PVE host.")
    parser.add_argument("--file", required=True, help="registry file to maintain")
    parser.add_argument("--set", action="append", default=[], metavar="VMID=UUID",
                        help="record (or update) one container identity")
    parser.add_argument("--remove", action="append", default=[], metavar="VMID",
                        help="forget one container identity")
    parser.add_argument("--get", metavar="VMID",
                        help="print the recorded UUID and exit")
    args = parser.parse_args(argv)

    try:
        table = read_table(args.file)

        if args.get is not None:
            vmid = int(args.get)
            if vmid not in table:
                print("ct_uuid_registry: vmid %d is not recorded in %s" % (vmid, args.file),
                      file=sys.stderr)
                return 1
            print(table[vmid])
            return 0

        if not args.set and not args.remove:
            parser.error("nothing to do: pass --set, --remove or --get")

        for value in args.set:
            vmid, system_uuid = parse_set(value)
            table[vmid] = system_uuid
        for value in args.remove:
            if not value.strip().isdigit():
                raise RegistryError("--remove %r: expected a vmid" % value)
            table.pop(int(value), None)

        values = list(table.values())
        if len(set(values)) != len(values):
            raise RegistryError("refusing to write a registry with duplicate UUIDs")
        print("changed" if write_table(args.file, table) else "unchanged")
    except RegistryError as exc:
        print("ct_uuid_registry: %s" % exc, file=sys.stderr)
        return 1
    except OSError as exc:
        print("ct_uuid_registry: %s" % exc, file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    sys.exit(main())
